package com.example.erp_service_sales.config;
import jakarta.servlet.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import org.springframework.stereotype.Component; import java.io.IOException;
@Component public class TenantFilter implements Filter { public void doFilter(ServletRequest request,ServletResponse response,FilterChain chain)throws IOException,ServletException { String tenant=((HttpServletRequest)request).getHeader("X-Tenant-ID"); if(tenant==null||!tenant.matches("[A-Za-z0-9_]{1,63}")){((HttpServletResponse)response).sendError(HttpServletResponse.SC_BAD_REQUEST,"A valid X-Tenant-ID header is required");return;} TenantContext.set(tenant); try{chain.doFilter(request,response);}finally{TenantContext.clear();} } }
